#include "game.hpp"
#include <algorithm>
#include <cctype>
#include <iostream>
#include <string>
#ifdef _WIN32
#include <conio.h>
#endif
namespace echodrive {
Game::Game():settings_(loadSettings("echodrive.cfg")),voice_(settings_.language){audio_.setListener({0,0,0},0);route_.load(settings_.street);}
void Game::menu()const{std::cout<<"\n=== EchoDrive 0.5 | Ahmed Samy Studio ===\n[ARROWS] up=تقدم down=فرامل left/right=توجيه\n[z/e] تقدم [x] فرامل [c/v] يسار/يمين [b/i] أسرع [n/o] أبطأ\n[a] آلي [m] يدوي [s/u] حالة [d/y] خريطة [f] التحكم [g] بوق [h] محرك\n[j/w] طقس [k/t] مرور [l] الشوارع [p] إيقاف مؤقت [r] إعادة [q] خروج\n> ";}
std::string Game::readInput()const{
#ifdef _WIN32
 int c=_getch(); if(c==0||c==224){int k=_getch();if(k==72)return "up";if(k==80)return "down";if(k==75)return "left";if(k==77)return "right";return "";} if(c==13)return "status"; return std::string(1,(char)std::tolower(c));
#else
 std::string x;std::getline(std::cin,x);for(auto&c:x)c=(char)std::tolower((unsigned char)c);return x;
#endif
}
void Game::selectStreet(){std::cout<<"اختر شارعًا من 1 إلى 15: ";int n=1;std::cin>>n;std::cin.ignore(10000,'\n');if(n<1||n>15)n=1;settings_.street=n;route_.load(n);const auto&x=allStreets()[n-1];auto assets=assetsForStreet(n);runtime_.setListener({0,0,0},0);runtime_.playLoop(assets.ambience,{0,0,8},0.45f);traffic_.reset(n);voice_.announce("بدأت "+x.ar+" من دولة "+x.country+". المسافة "+std::to_string((int)route_.state().lengthM)+" متر","Starting "+x.en+" in "+x.country+". Route length "+std::to_string((int)route_.state().lengthM)+" meters");}
void Game::selectVehicle(){std::cout<<"اختر سيارة من 1 إلى 25: ";int n=1;std::cin>>n;std::cin.ignore(10000,'\n');if(n<1||n>25)n=1;vehicle_=n;auto assets=assetsForStreet(settings_.street);runtime_.playLoop(assets.engine,{0,0,1},0.70f);const auto&x=allVehicles()[n-1];voice_.announce("اخترت "+x.ar+"، السرعة القصوى "+std::to_string(x.topSpeed),"Selected "+x.en+", top speed "+std::to_string(x.topSpeed));}
Command Game::parse(const std::string&r)const{if(r=="1"||r=="up"||r=="forward"||r=="z"||r=="e"||r=="تقدم")return Command::Forward;if(r=="2"||r=="down"||r=="stop"||r=="x"||r=="توقف"||r=="فرامل")return Command::Brake;if(r=="3"||r=="right"||r=="v"||r=="يمين")return Command::Right;if(r=="4"||r=="left"||r=="c"||r=="يسار")return Command::Left;if(r=="5"||r=="+"||r=="b"||r=="i"||r=="أسرع")return Command::Faster;if(r=="6"||r=="-"||r=="n"||r=="o"||r=="أبطئ")return Command::Slower;if(r=="a"||r=="auto"||r=="قيادة آلية")return Command::Auto;if(r=="m"||r=="manual"||r=="قيادة يدوية")return Command::Manual;if(r=="s"||r=="u"||r=="status"||r=="حالة")return Command::Repeat;if(r=="r"||r=="reset"||r=="إعادة")return Command::Reset;if(r=="l"||r=="streets")return Command::ListStreets;if(r=="vehicles"||r=="listvehicles")return Command::ListVehicles;if(r=="w"||r=="j"||r=="weather"||r=="طقس")return Command::WeatherCycle;if(r=="t"||r=="k"||r=="traffic"||r=="مرور")return Command::Traffic;if(r=="d"||r=="y"||r=="map"||r=="خريطة")return Command::Map;if(r=="f"||r=="controls"||r=="تحكم")return Command::Controls;if(r=="g"||r=="horn")return Command::Horn;if(r=="p"||r=="pause")return Command::Pause;if(r=="h"||r=="engine")return Command::Engine;if(r=="q"||r=="quit"||r=="خروج")return Command::Quit;return Command::Unknown;}
void Game::status()const{std::string d=heading_<0?"يسار":heading_>0?"يمين":"مستقيم";std::string e=heading_<0?"left":heading_>0?"right":"straight";const auto&car=allVehicles()[vehicle_-1];const auto&ws=weather_.state();const auto&rs=route_.state();voice_.announce("السرعة "+std::to_string((int)speed_)+" كيلومتر، قطعت "+std::to_string((int)rs.progressM)+" متر، متبقي "+std::to_string((int)(rs.lengthM-rs.progressM))+" متر، الاتجاه "+d+"، المعلم التالي "+route_.nextLandmark(true)+"، السيارة "+car.ar+"، الطقس "+weather_.name(true)+"، الحرارة "+std::to_string(ws.temperature),"Speed "+std::to_string((int)speed_)+" kilometers per hour, traveled "+std::to_string((int)rs.progressM)+" meters, remaining "+std::to_string((int)(rs.lengthM-rs.progressM))+" meters, direction "+e+", next landmark "+route_.nextLandmark(false)+", vehicle "+car.en+", weather "+weather_.name(false)+", temperature "+std::to_string(ws.temperature));}
void Game::showControls()const{std::cout<<"\n--- Controls ---\nArrows: up forward, down brake, left/right steer\nZ/E forward | X brake | C/V left/right | B/I faster | N/O slower\nA auto | M manual | S/U status | D/Y map | F controls | G horn | H engine\nJ/W weather | K/T traffic | L streets | P pause | R reset | Q quit\n";voice_.announce("الأسهم للحركة. تم عرض كل الاختصارات","Arrow controls and all shortcuts are shown");}
void Game::listContent()const{std::cout<<"\n--- 15 Streets ---\n";for(const auto&s:allStreets())std::cout<<s.id<<". "<<s.en<<" — "<<s.country<<"\n";std::cout<<"\n--- 25 Vehicles ---\n";for(const auto&v:allVehicles())std::cout<<v.id<<". "<<v.en<<" ["<<v.category<<"] max "<<v.topSpeed<<" km/h\n";}
void Game::handle(Command c){if(paused_&&c!=Command::Pause&&c!=Command::Quit){voice_.announce("اللعبة متوقفة، اضغط p للمتابعة","Game paused, press p to resume");return;}switch(c){case Command::Forward:if(!engineOn_)engineOn_=true;speed_=std::min((double)allVehicles()[vehicle_-1].topSpeed,speed_+8);route_.advance(speed_);traffic_.tick(speed_,settings_.automaticDriving);voice_.announce("تقدم. "+traffic_.nearestAlert(true),"Moving forward. "+traffic_.nearestAlert(false));break;case Command::Brake:speed_=std::max(0.0,speed_-20);route_.advance(speed_*.15);traffic_.tick(speed_,settings_.automaticDriving);voice_.announce("فرامل","Braking");break;case Command::Right:heading_=1;audio_.setListener({0,0,0},0.25);voice_.announce("يمين، الصوت من الجهة اليمنى","Turning right, audio cue on the right");break;case Command::Left:heading_=-1;audio_.setListener({0,0,0},-0.25);voice_.announce("يسار، الصوت من الجهة اليسرى","Turning left, audio cue on the left");break;case Command::Faster:speed_=std::min((double)allVehicles()[vehicle_-1].topSpeed,speed_+15);route_.advance(speed_);traffic_.tick(speed_,settings_.automaticDriving);status();break;case Command::Slower:speed_=std::max(0.0,speed_-15);status();break;case Command::Auto:settings_.automaticDriving=true;voice_.announce("تم تشغيل القيادة الآلية","Automatic driving enabled");break;case Command::Manual:settings_.automaticDriving=false;voice_.announce("تم تشغيل القيادة اليدوية","Manual driving enabled");break;case Command::Reset:speed_=0;heading_=0;route_.reset();audio_.setListener({0,0,0},0);traffic_.reset(settings_.street);weather_.set(Weather::Clear);voice_.announce("أعيدت الرحلة والطقس إلى الصحو","Trip and weather reset to clear");break;case Command::Repeat:status();break;case Command::ListStreets:case Command::ListVehicles:listContent();break;case Command::WeatherCycle:weather_.cycle();runtime_.playLoop(weather_.ambiencePath(),{0,0,5},0.38f);voice_.announce("الطقس الآن "+weather_.name(true)+". "+weather_.advisory(true),"Weather is now "+weather_.name(false)+". "+weather_.advisory(false));break;case Command::Traffic:traffic_.tick(speed_,settings_.automaticDriving);voice_.announce(traffic_.nearestAlert(true),traffic_.nearestAlert(false));break;case Command::Map:voice_.announce(route_.render(true),route_.render(false));std::cout<<route_.render(true)<<"\n";break;case Command::Controls:showControls();break;case Command::Horn:runtime_.playOneShot("assets/audio/vehicles/Car_Horn.ogg",{1,0,3},0.8f);voice_.announce("بوق","Horn");break;case Command::Pause:paused_=!paused_;voice_.announce(paused_?"تم إيقاف اللعبة":"تم استئناف اللعبة",paused_?"Game paused":"Game resumed");break;case Command::Engine:engineOn_=!engineOn_;if(!engineOn_)speed_=0;voice_.announce(engineOn_?"تم تشغيل المحرك":"تم إيقاف المحرك",engineOn_?"Engine on":"Engine off");break;case Command::Quit:saveSettings(settings_,"echodrive.cfg");voice_.announce("إلى اللقاء","Goodbye");break;case Command::Unknown:voice_.announce("لم أفهم الأمر","Command not understood");}}
void Game::run(){voice_.announce("مرحبًا بك في EchoDrive. الأسهم والاختصارات والخريطة مفعلة.","Welcome to EchoDrive. Arrows, shortcuts and route map are enabled.");selectStreet();selectVehicle();for(;;){menu();std::string x=readInput();Command c=parse(x);handle(c);if(c==Command::Quit)break;}}
}
